   626      // Check whether a type (or any of its nested fields) contains types that
   627      // cannot be marshalled to/from an AnyValue. Rejects types that would crash
   628      // in emitMarshallingCode or produce invalid output for the current target.
   629      bool containsUnmarshalableType(IRType* type)
   630      {
   631          switch (type->getOp())
   632          {
   633          case kIROp_AtomicType:
   634          case kIROp_UnsizedArrayType:
   635              return true;
   636  
   637          case kIROp_PtrType:
   638              {
   639                  // SPIRV generates incompatible struct types for Function vs
   640                  // PhysicalStorageBuffer storage classes. Pointers to concrete
   641                  // structs packed into AnyValue produce type mismatches in the
   642                  // generated SPIRV. CPU and CUDA handle this correctly.
   643                  // Interface pointers are allowed: they point to existential
   644                  // tuples that are already handled by dynamic dispatch lowering.
   645                  if (!isSPIRV(targetProgram->getTargetReq()->getTarget()))
   646                      return false;
   647                  auto ptrType = cast<IRPtrTypeBase>(type);
   648                  auto valueType = ptrType->getValueType();
   649                  return valueType->getOp() != kIROp_InterfaceType;
   650              }
   651  
   652          case kIROp_StructType:
   653              {
   654                  auto structType = cast<IRStructType>(type);
   655                  for (auto field : structType->getFields())
   656                  {
   657                      if (containsUnmarshalableType(field->getFieldType()))
   658                          return true;
   659                  }
   660                  return false;
   661              }
   662  
   663          case kIROp_ArrayType:
   664              {
   665                  auto arrayType = cast<IRArrayType>(type);
   666                  return containsUnmarshalableType((IRType*)arrayType->getElementType());
   667              }
   668  
   669          case kIROp_VectorType:
   670              {
   671                  auto vectorType = cast<IRVectorType>(type);
   672                  return containsUnmarshalableType((IRType*)vectorType->getElementType());
   673              }
   674  
   675          case kIROp_MatrixType:
   676              {
   677                  auto matrixType = cast<IRMatrixType>(type);
   678                  return containsUnmarshalableType((IRType*)matrixType->getElementType());
   679              }
   680  
   681          default:
   682              return false;
   683          }
   684      }
